<script setup>
import { computed,ref,watch } from 'vue';
import { api,errorMessage } from '../api';
import { money,foodImage,loadConfiguration } from '../store';
const props=defineProps({resource:{type:String,required:true}});
const rows=ref([]);const categories=ref([]);const formOpen=ref(false);const editing=ref(null);const busy=ref(false);const error=ref('');const search=ref('');const page=ref(1);const lastPage=ref(1);const deleteTarget=ref(null);const form=ref({});const imageInput=ref(null);
const isProduct=computed(()=>['products','deals'].includes(props.resource));
const title=computed(()=>({'products':'Food menu','deals':'Deals','categories':'Categories','coupons':'Coupons','delivery-areas':'Delivery areas'})[props.resource]);
const defaults=()=>isProduct.value ? {name:'',slug:'',category_id:'',description:'',image:'',price:0,discount_price:null,preparation_time:20,is_active:true,is_available:true,is_featured:false,is_deal:props.resource==='deals',deal_contents:[],variations:[],addons:[]} : props.resource==='categories' ? {name:'',slug:'',description:'',image:'',sort_order:0,is_active:true} : props.resource==='coupons' ? {code:'',discount_type:'percentage',discount_value:20,minimum_order:0,maximum_discount:null,start_date:null,expiry_date:null,usage_limit:null,is_active:true} : {name:'',city:'Lahore',fee:null,is_active:true};
const slugify=value=>value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
async function load(){busy.value=true;error.value='';try{const {data}=await api.get(`/admin/${props.resource}`,{params:{page:page.value,search:search.value || undefined}});rows.value=data.data;lastPage.value=data.last_page;}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
async function loadCategories(){const result=[];let current=1;let max=1;do{const {data}=await api.get('/admin/categories',{params:{page:current}});result.push(...data.data);max=data.last_page;current++;}while(current<=max);categories.value=result;}
async function edit(record=null){error.value='';try{editing.value=record?.id || null;form.value=record ? {...defaults(),...(await api.get(`/admin/${props.resource}/${record.id}`)).data.data} : defaults();for(const field of ['start_date','expiry_date'])if(form.value[field])form.value[field]=form.value[field].slice(0,10);formOpen.value=true;if(isProduct.value){await loadCategories();if(!form.value.category_id)form.value.category_id=categories.value[0]?.id || '';}}catch(failure){error.value=errorMessage(failure);}}

async function save(){busy.value=true;error.value='';try{const payload={...form.value};if(payload.slug==='' && payload.name)payload.slug=slugify(payload.name);if(payload.code)payload.code=payload.code.trim().toUpperCase();for(const field of ['discount_price','maximum_discount','usage_limit','fee','start_date','expiry_date'])if(payload[field]==='')payload[field]=null;await api[editing.value ? 'put':'post'](`/admin/${props.resource}${editing.value ? '/'+editing.value : ''}`,payload);formOpen.value=false;await loadConfiguration();await load();}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
async function remove(){busy.value=true;error.value='';try{await api.delete(`/admin/${props.resource}/${deleteTarget.value.id}`);deleteTarget.value=null;await loadConfiguration();await load();}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
async function upload(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const payload=new FormData();payload.append('image',file);form.value.image=(await api.post('/admin/images',payload)).data.image;}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;event.target.value='';}}
watch(()=>props.resource,()=>{page.value=1;search.value='';formOpen.value=false;deleteTarget.value=null;load();},{immediate:true});
</script>
<template><div><div class="admin-page-heading"><div><div class="eyebrow">YOUR RESTAURANT · YOUR WAY</div><h1>{{ title }}</h1><p>{{ isProduct ? 'Keep your food fresh, your prices clear, and your menu up to date.' : 'Manage the details that make every order run smoothly.' }}</p></div><button class="button" @click="edit()">Add {{ resource==='delivery-areas' ? 'area' : resource==='categories' ? 'category' : resource==='coupons' ? 'coupon' : resource==='deals' ? 'deal' : 'food item' }} +</button></div><div v-if="error" class="form-error" role="alert">{{ error }}</div><div v-if="deleteTarget" class="delete-confirm panel"><p>Delete <strong>{{ deleteTarget.name || deleteTarget.code }}</strong>? Past order details are preserved. Categories with products cannot be deleted.</p><div class="row-actions"><button class="button button-small" @click="remove" :disabled="busy">Delete record</button><button class="text-button" @click="deleteTarget=null">Keep it</button></div></div><div v-if="formOpen" class="panel catalog-editor"><div class="section-heading"><h2>{{ editing ? 'Edit' : 'Add' }} {{ resource==='products' ? 'food item' : resource==='deals' ? 'deal' : resource==='categories' ? 'category' : resource==='coupons' ? 'coupon' : 'delivery area' }}</h2><button class="text-button" @click="formOpen=false">Close ×</button></div><form @submit.prevent="save" class="form-grid"><template v-if="resource==='coupons'"><label>Code<input v-model="form.code" required maxlength="50" placeholder="WELCOME20"></label><label>Discount type<select v-model="form.discount_type"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label>Discount value<input v-model.number="form.discount_value" type="number" min="0" :max="form.discount_type==='percentage' ? 100 : 999999" step=".01" required></label><label>Minimum subtotal<input v-model.number="form.minimum_order" type="number" min="0" step=".01" required></label><label>Maximum discount <span>(optional)</span><input v-model.number="form.maximum_discount" type="number" min="0" step=".01"></label><label>Usage limit <span>(optional)</span><input v-model.number="form.usage_limit" type="number" min="1" step="1"></label><label>Start date<input v-model="form.start_date" type="date"></label><label>Expiry date<input v-model="form.expiry_date" type="date"></label><p v-if="editing" class="full-width">Used {{ form.used_count || 0 }} times. Usage count is managed by checkout.</p></template><template v-else><label>Name<input v-model="form.name" required maxlength="100" @input="!editing && resource!=='delivery-areas' && (form.slug=slugify(form.name))"></label><label v-if="resource!=='delivery-areas'">Slug<input v-model="form.slug" required pattern="[a-zA-Z0-9_-]+" maxlength="120"></label><label v-if="resource==='delivery-areas'">City<input v-model="form.city" required maxlength="100"></label><label v-if="resource==='delivery-areas'">Delivery fee <span>(blank uses default)</span><input v-model.number="form.fee" type="number" min="0" step=".01"></label><template v-else><label v-if="isProduct">Category<select v-model.number="form.category_id" required><option value="" disabled>Select a category</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}{{ !category.is_active ? ' (disabled)' : '' }}</option></select></label><label v-if="!isProduct">Sort order<input v-model.number="form.sort_order" type="number" min="0" max="1000" required></label><label class="full-width">Description<textarea v-model="form.description" :required="isProduct" maxlength="3000"></textarea></label><label class="full-width">Image URL or photo ID<input v-model="form.image" placeholder="https://… or upload an image below"></label><label class="full-width">Upload image <span>(JPG, PNG, WebP · up to 2 MB)</span><input type="file" accept="image/jpeg,image/png,image/webp" @change="upload"></label><img v-if="form.image" class="editor-image" :src="foodImage(form.image)" alt="Menu image preview"><template v-if="isProduct"><label>Original price<input v-model.number="form.price" type="number" min="0" max="999999" step=".01" required></label><label>Discount price <span>(optional)</span><input v-model.number="form.discount_price" type="number" min="0" :max="form.price" step=".01"></label><label>Preparation time <span>(minutes)</span><input v-model.number="form.preparation_time" type="number" min="1" max="180" required></label><div class="editor-checks"><label class="check-label"><input v-model="form.is_available" type="checkbox"> Available to order</label><label class="check-label"><input v-model="form.is_featured" type="checkbox"> Featured</label><label class="check-label"><input v-model="form.is_deal" type="checkbox"> Special deal</label></div><div v-if="form.is_deal" class="full-width repeatable-editor"><h3>What’s included in this deal?</h3><div v-for="(_,index) in form.deal_contents" :key="index" class="repeatable-row"><input v-model="form.deal_contents[index]" required maxlength="150" aria-label="Deal contents"><button type="button" @click="form.deal_contents.splice(index,1)" aria-label="Remove deal item">×</button></div><button type="button" class="text-button" @click="form.deal_contents.push('')" :disabled="form.deal_contents.length>=20">Add included item +</button></div><fieldset v-for="relation in ['variations','addons']" :key="relation" class="full-width repeatable-editor"><legend>{{ relation==='variations' ? 'Sizes / variations' : 'Optional add-ons' }}</legend><div v-for="(option,index) in form[relation]" :key="index" class="repeatable-row"><input v-model="option.name" placeholder="Name" required maxlength="80" :aria-label="`${relation} name ${index+1}`"><input v-model.number="option.price" type="number" min="0" max="999999" step=".01" placeholder="Price" required :aria-label="`${relation} price ${index+1}`"><label class="check-label"><input v-model="option.is_active" type="checkbox"> Active</label><button type="button" @click="form[relation].splice(index,1)" :aria-label="`Remove ${relation} ${index+1}`">×</button></div><button type="button" class="text-button" @click="form[relation].push({name:'',price:0,is_active:true})" :disabled="form[relation].length>=10">Add {{ relation==='variations' ? 'size' : 'extra' }} +</button></fieldset></template></template></template><label class="check-label full-width"><input v-model="form.is_active" type="checkbox"> Enabled</label><div class="row-actions full-width"><button class="button" :disabled="busy">{{ busy ? 'Saving…' : 'Save changes' }}</button><button type="button" class="text-button" @click="formOpen=false">Cancel</button></div></form></div><div class="panel"><form class="admin-list-toolbar" @submit.prevent="page=1;load()"><label class="search-field"><span>⌕</span><input v-model="search" :placeholder="`Search ${title.toLowerCase()}…`" :aria-label="`Search ${title.toLowerCase()}`"></label><button class="text-button" :disabled="busy">Search →</button><button type="button" class="text-button" @click="load" :disabled="busy">Refresh ↻</button></form><div class="table-scroll"><table><thead><tr><th>{{ resource==='coupons' ? 'Code' : 'Name' }}</th><th>{{ isProduct ? 'Category' : resource==='coupons' ? 'Discount' : resource==='delivery-areas' ? 'City' : 'Sort order' }}</th><th v-if="isProduct || resource==='delivery-areas'">{{ isProduct ? 'Price' : 'Fee' }}</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="record in rows" :key="record.id"><td><div class="table-food"><img v-if="isProduct" :src="foodImage(record.image,100)" alt=""><strong>{{ record.name || record.code }}</strong></div></td><td>{{ isProduct ? record.category?.name : resource==='coupons' ? (record.discount_type==='percentage' ? `${record.discount_value}%` : money(record.discount_value)) : resource==='delivery-areas' ? record.city : record.sort_order }}</td><td v-if="isProduct || resource==='delivery-areas'">{{ money(isProduct ? record.discount_price ?? record.price : record.fee) }}</td><td><span class="status-badge" :data-status="record.is_active && record.is_available!==false ? 'confirmed' : 'cancelled'">{{ !record.is_active ? 'Disabled' : record.is_available===false ? 'Unavailable' : 'Active' }}</span></td><td><div class="row-actions"><button @click="edit(record)">Edit</button><button class="accent" @click="deleteTarget=record">Delete</button></div></td></tr><tr v-if="!rows.length"><td colspan="5">{{ busy ? 'Loading…' : 'No records found. Add your first one above.' }}</td></tr></tbody></table></div><div class="pagination"><button :disabled="page<=1 || busy" @click="page--;load()">← Previous</button><span>{{ page }} / {{ lastPage }}</span><button :disabled="page>=lastPage || busy" @click="page++;load()">Next →</button></div></div></div></template>
